<?php
require_once __DIR__.'/../includes/functions.php';require_role('teacher');verify_csrf();
$teacherQ=db()->prepare('SELECT teacher_id FROM teachers WHERE user_id=?');$teacherQ->execute([current_user()['user_id']]);$teacherId=(int)$teacherQ->fetchColumn();
$assign=db()->prepare('SELECT ts.*,s.subject_name,c.class_name FROM teacher_subjects ts JOIN subjects s ON s.subject_id=ts.subject_id JOIN classes c ON c.class_id=ts.class_id WHERE ts.teacher_id=?');$assign->execute([$teacherId]);$assignments=$assign->fetchAll();
$students=[];$selected=(int)($_GET['assignment']??$_POST['assignment']??0);$examId=(int)($_GET['exam']??$_POST['exam']??0);
if($selected){$valid=db()->prepare('SELECT * FROM teacher_subjects WHERE assignment_id=? AND teacher_id=?');$valid->execute([$selected,$teacherId]);$a=$valid->fetch();if(!$a){http_response_code(403);exit('Not assigned to this class.');}
 $q=db()->prepare('SELECT s.student_id,s.roll_number,u.name,m.obtained_marks,m.total_marks,m.mark_id FROM enrollments en JOIN students s ON s.student_id=en.student_id JOIN users u ON u.user_id=s.user_id LEFT JOIN marks m ON m.student_id=s.student_id AND m.subject_id=? AND m.exam_id=? WHERE en.class_id=? ORDER BY s.roll_number');$q->execute([$a['subject_id'],$examId,$a['class_id']]);$students=$q->fetchAll();}
$exams=db()->query('SELECT * FROM exams ORDER BY exam_id DESC')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_marks'])){
 $q=db()->prepare('SELECT * FROM teacher_subjects WHERE assignment_id=? AND teacher_id=?');$q->execute([$selected,$teacherId]);$a=$q->fetch();if(!$a){http_response_code(403);exit('Forbidden');}
 $pdo=db();$pdo->beginTransaction();try{
 foreach($_POST['marks']??[] as $sid=>$value){$sid=(int)$sid;$obt=filter_var($value,FILTER_VALIDATE_FLOAT);$total=(float)($_POST['total'][$sid]??100);if($obt===false||$obt<0||$total<=0||$obt>$total)throw new RuntimeException('Marks must be between zero and maximum marks.');
 $check=$pdo->prepare('SELECT mark_id,obtained_marks FROM marks WHERE student_id=? AND subject_id=? AND exam_id=?');$check->execute([$sid,$a['subject_id'],$examId]);$old=$check->fetch();
 if($old){$pdo->prepare('UPDATE marks SET obtained_marks=?,total_marks=?,updated_by=?,updated_at=NOW() WHERE mark_id=?')->execute([$obt,$total,current_user()['user_id'],$old['mark_id']]);$pdo->prepare('INSERT INTO result_history(user_id,student_id,subject_id,exam_id,old_marks,new_marks,reason) VALUES(?,?,?,?,?,?,?)')->execute([current_user()['user_id'],$sid,$a['subject_id'],$examId,$old['obtained_marks'],$obt,trim($_POST['reason']??'')]);}
 else {$pdo->prepare('INSERT INTO marks(student_id,subject_id,exam_id,obtained_marks,total_marks,updated_by) VALUES(?,?,?,?,?,?)')->execute([$sid,$a['subject_id'],$examId,$obt,$total,current_user()['user_id']]);$pdo->prepare('INSERT INTO result_history(user_id,student_id,subject_id,exam_id,old_marks,new_marks,reason) VALUES(?,?,?,?,?,?,?)')->execute([current_user()['user_id'],$sid,$a['subject_id'],$examId,null,$obt,'Initial entry']);}
 }
 $pdo->commit();audit('Saved marks for assignment '.$selected);flash('success','Marks saved and history recorded.');
 }catch(Throwable $e){$pdo->rollBack();flash('danger',$e instanceof RuntimeException?$e->getMessage():'Unable to save marks.');}redirect('marks.php?assignment='.$selected.'&exam='.$examId);
}
include __DIR__.'/../includes/header.php';?>
<div class="card mb-3"><div class="card-header">Select class, subject and examination</div><div class="card-body"><form class="row g-2" method="get"><div class="col-md-5"><select class="form-select" name="assignment" required><option value="">Assigned subject / class</option><?php foreach($assignments as $a):?><option value="<?=$a['assignment_id']?>" <?=$selected===$a['assignment_id']?'selected':''?>><?=e($a['subject_name'].' · '.$a['class_name'])?></option><?php endforeach;?></select></div><div class="col-md-5"><select class="form-select" name="exam" required><option value="">Examination</option><?php foreach($exams as $x):?><option value="<?=$x['exam_id']?>" <?=$examId===$x['exam_id']?'selected':''?>><?=e($x['exam_name'].' · '.$x['academic_session'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Load students</button></div></form></div></div>
<?php if($selected && $examId):?><div class="card"><div class="card-header">Enter / update marks</div><div class="card-body"><?php if(!$students):?><div class="empty-state">No students enrolled in this class yet. Add enrollments in the database first.</div><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="assignment" value="<?=$selected?>"><input type="hidden" name="exam" value="<?=$examId?>"><div class="table-responsive"><table class="table"><thead><tr><th>Roll number</th><th>Student</th><th>Obtained marks</th><th>Maximum</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><?=e($s['roll_number'])?></td><td><?=e($s['name'])?></td><td><input class="form-control" type="number" min="0" step=".01" name="marks[<?=$s['student_id']?>]" value="<?=e((string)($s['obtained_marks']??''))?>" required></td><td><input class="form-control" type="number" min="1" step=".01" name="total[<?=$s['student_id']?>]" value="<?=e((string)($s['total_marks']??100))?>" required></td></tr><?php endforeach;?></tbody></table></div><div class="mb-3"><label class="form-label">Reason for changes (if applicable)</label><input class="form-control" name="reason" placeholder="e.g. correction after rechecking"></div><button class="btn btn-primary" name="save_marks" value="1">Save marks</button></form><?php endif;?></div></div><?php endif;?>
<?php include __DIR__.'/../includes/footer.php';?>